function dump(n, d, lines) {
  var s = "  ".repeat(d) + n.name + " [" + n.type + "]";
  if (n.type === "TEXT") { s += " chars='" + n.characters + "' font=" + JSON.stringify(n.fontName) + " size=" + n.fontSize; if (n.fills && n.fills[0] && n.fills[0].type==="SOLID") s += " color=" + JSON.stringify(n.fills[0].color); }
  if ("fills" in n && Array.isArray(n.fills) && n.fills.length) { s += " fills=" + JSON.stringify(n.fills.map(function(f){return f.type==="SOLID"?{t:"S",c:f.color,o:f.opacity}:{t:f.type};})); }
  if ("cornerRadius" in n && n.cornerRadius !== 0 && n.cornerRadius !== figma.mixed) s += " r=" + n.cornerRadius;
  if ("strokes" in n && n.strokes && n.strokes.length) s += " strokes=" + JSON.stringify(n.strokes.map(function(f){return {c:f.color};})) + " w=" + n.strokeWeight;
  if ("effects" in n && n.effects && n.effects.length) s += " fx=" + JSON.stringify(n.effects.map(function(e){return e.type;}));
  if ("layoutMode" in n && n.layoutMode !== "NONE") s += " layout=" + n.layoutMode + " pad=" + n.paddingLeft + "," + n.paddingTop + "," + n.paddingRight + "," + n.paddingBottom + " gap=" + n.itemSpacing + " align=" + n.primaryAxisAlignItems + "/" + n.counterAxisAlignItems;
  if ("clipsContent" in n) s += " clip=" + n.clipsContent;
  lines.push(s);
  if ("children" in n) { for (var i=0;i<n.children.length;i++) dump(n.children[i], d+1, lines); }
}
