function dump(n, depth, out){
  var pad = "";
  for (var i=0;i<depth;i++) pad += "  ";
  var line = pad + n.type + " '" + n.name + "' " + Math.round(n.width) + "x" + Math.round(n.height);
  if (n.type === "TEXT") line += " chars='" + n.characters + "' font=" + n.fontName.family + "/" + n.fontName.style + " size=" + n.fontSize;
  if (n.type === "COMPONENT" || n.type === "INSTANCE") {
    try { var props = n.componentPropertyDefinitions; if (props) line += " props=" + JSON.stringify(Object.keys(props)); } catch(e){}
  }
  out.push(line);
  if ("children" in n) { for (var j=0;j<n.children.length;j++) dump(n.children[j], depth+1, out); }
}
