// find the two circles and two icon instances we added (ellipses + google/facebook icons)
var circles=f3.findAll(function(n){return n.type==="ELLIPSE";});
// circles: google at x41, fb at x225 -> move to 31 and 215
circles.forEach(function(c){
  if(Math.round(c.x)===41) c.x=31;
  if(Math.round(c.x)===225) c.x=215;
});
var icons=f3.findAll(function(n){return n.type==="INSTANCE" && (n.name.indexOf("Google")>=0||n.name.indexOf("Facebook")>=0);});
icons.forEach(function(ic){
  // center over its circle
  var cx = ic.x; // currently 41+... recompute: place centered on circle
});
// reposition icons centered on circles (circle centers now 31+16=47 and 215+16=231)
icons.forEach(function(ic){
  var targetCx = (Math.round(ic.x) < 150) ? 47 : 231;
  ic.x = targetCx - ic.width/2;
  ic.y = 694 + 16 - ic.height/2;
});
return "circles:"+circles.map(function(c){return Math.round(c.x);}).join(",")+" icons:"+icons.map(function(i){return i.name+"@"+Math.round(i.x);}).join(",");

