function fitImage(compId,cx,cy,maxW,maxH,parent){
  return figma.getNodeByIdAsync(compId).then(function(c){
    var inst=c.createInstance();
    var s=Math.min(maxW/inst.width,maxH/inst.height);
    inst.resize(inst.width*s,inst.height*s);
    inst.x=cx-inst.width/2; inst.y=cy-inst.height/2;
    parent.appendChild(inst); return inst;
  });
}
