function imgInfo(c){
  var img=c.findOne(function(n){return n.name==="Image";});
  return c.name+": Image @"+img.x+","+img.y+" "+img.width+"x"+img.height+" fills="+JSON.stringify(img.fills.map(function(f){return f.type;}))+" corner="+img.cornerRadius;
}
