var tb=await figma.getNodeByIdAsync("13:2");
function dump(n,d,out){
  var pad=""; for(var i=0;i<d;i++)pad+="  ";
  var line=pad+n.type+" '"+n.name+"' "+Math.round(n.width)+"x"+Math.round(n.height)+" @"+Math.round(n.x)+","+Math.round(n.y);
  if(n.type==="TEXT")line+=" chars='"+n.characters+"'";
  if(n.type==="VECTOR"||n.type==="ELLIPSE"||n.type==="FRAME"){try{line+=" fills="+JSON.stringify(n.fills.map(function(f){return f.type==="SOLID"?[Math.round(f.color.r*255),Math.round(f.color.g*255),Math.round(f.color.b*255)]:f.type;}));}catch(e){}}
  out.push(line);
  if("children" in n){for(var j=0;j<n.children.length;j++)dump(n.children[j],d+1,out);}
}
var out=[];dump(tb,0,out);
return out.join("\n");
